CREATE TABLE IF NOT EXISTS event_records (id INTEGER PRIMARY KEY AUTOINCREMENT,event_code TEXT NOT NULL UNIQUE,app_id TEXT NOT NULL DEFAULT 'principal-ed',title TEXT NOT NULL,event_type TEXT NOT NULL CHECK(event_type IN ('meeting','trip','performance','sports','conference','training','ceremony','recruitment','wellbeing','academic','other')),purpose TEXT NOT NULL,description TEXT,starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,timezone TEXT NOT NULL DEFAULT 'Asia/Riyadh',all_day INTEGER NOT NULL DEFAULT 0 CHECK(all_day IN (0,1)),location_summary TEXT,audience_id INTEGER,calendar_entry_id INTEGER,owner_type TEXT NOT NULL DEFAULT 'user',owner_id TEXT NOT NULL,visibility TEXT NOT NULL DEFAULT 'internal' CHECK(visibility IN ('internal','restricted','public_candidate')),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','planning','ready','approved','in_progress','completed','cancelled','withdrawn')),cancellation_reason TEXT,completed_at TEXT,completed_by TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')),FOREIGN KEY(audience_id) REFERENCES audiences(id) ON DELETE SET NULL,FOREIGN KEY(calendar_entry_id) REFERENCES calendar_entries(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS event_record_history (id INTEGER PRIMARY KEY AUTOINCREMENT,event_id INTEGER NOT NULL,action TEXT NOT NULL,from_status TEXT,to_status TEXT,reason TEXT,actor_id TEXT NOT NULL,snapshot TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),FOREIGN KEY(event_id) REFERENCES event_records(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_event_records_app ON event_records(app_id,status,starts_at);CREATE INDEX IF NOT EXISTS idx_event_records_owner ON event_records(app_id,owner_type,owner_id,status);CREATE INDEX IF NOT EXISTS idx_event_history ON event_record_history(event_id,created_at);
